    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'Facility Hazardous Materials or Condition Type', [CedsElementTechnicalName] = N'FacilityHazardousMaterialsOrConditionType', [CedsOptionSetDescription] = N'Refrigerants', [CedsOptionSetDefinition] = N'A refrigerant is a compound used in a heat cycle that reversibly undergoes a phase change from a gas to a liquid. Traditionally, fluorocarbons, especially chlorofluorocarbons were used as refrigerants, but they are being phased out because of their ozone depletion effects. Other refrigerants are ammonia, sulfur dioxide, carbon dioxide, and non-halogenated hydrocarbons such as methane. It is illegal to release refrigerants into the atmosphere (intentional or accidental) because they can cause severe damage to the ozone layer. When CFCs are removed they should be recycled to clean out any contaminants and return it to a usable condition. Refrigerants should never be mixed together. Some CFCs must be managed as hazardous waste even if recycled, and special precautions are required for their transport, depending on the legislation of the country''s government.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001874' AND [CedsOptionSetCode] = N'13671'
