    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'Financial Account Balance Sheet Code', [CedsElementTechnicalName] = N'FinancialAccountBalanceSheetCode', [CedsOptionSetDescription] = N'Site Improvements', [CedsOptionSetDefinition] = N'A capital asset account that reflects the value of nonpermanent improvements to building sites, other than buildings, that add value to land. Examples of such improvements are fences, retaining walls, sidewalks, pavements, gutters, tunnels, and bridges. If the improvements are purchased or constructed, this account contains the purchase or contract price. If improvements are obtained by gift, it reflects the fair value at the time of acquisition. Site improvements are improvements that have a limited useful life. Because these improvements decrease in their value/usefulness over time, it is appropriate to depreciate these assets. Therefore, all capitalized site improvements should be depreciated over their expected useful life.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001353' AND [CedsOptionSetCode] = N'221'
