    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'IPEDS Finance FASB Functional Expense Category', [CedsElementTechnicalName] = N'IPEDSFinanceFASBFunctionalExpenseCategory', [CedsOptionSetDescription] = N'Instruction', [CedsOptionSetDefinition] = N'A functional expense category that includes expenses of the colleges, schools, departments, and other instructional divisions of the institution and expenses for departmental research and public service that are not separately budgeted. Includes general academic instruction, occupational and vocational instruction, community education, preparatory and adult basic education, and regular, special, and extension sessions. Also includes expenses for both credit and non-credit activities. Excludes expenses for academic administration where the primary function is administration (e.g., academic deans). Information technology expenses related to instructional activities if the institution separately budgets and expenses information technology resources are included (otherwise these expenses are included in academic support). Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001659' AND [CedsOptionSetCode] = N'Instruction'
