    IF NOT EXISTS (SELECT 1 FROM [CEDS].[CedsOptionSetMapping] WHERE [CedsGlobalId] = N'001675' AND [CedsOptionSetCode] = N'Academicsupport')
    BEGIN
        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'IPEDS Finance GASB Functional Expense Category', N'IPEDSFinanceGASBFunctionalExpenseCategory', N'001675', N'Academicsupport', N'Academic support', N'A functional expense category that includes expenses of activities and services that support the institution''s primary missions of instruction, research, and public service. It includes the retention, preservation, and display of educational materials (for example, libraries, museums, and galleries); organized activities that provide support services to the academic functions of the institution (such as a demonstration school associated with a college of education or veterinary and dental clinics if their primary purpose is to support the instructional program); media such as audiovisual services; academic administration (including academic deans but not department chairpersons); and formally organized and separately budgeted academic personnel development and course and curriculum development expenses. Also included are information technology expenses related to academic support activities; if an institution does not separately budget and expense information technology resources, the costs associated with the three primary programs will be applied to this function and the remainder to institutional support. Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'IPEDS Finance GASB Functional Expense Category', [CedsElementTechnicalName] = N'IPEDSFinanceGASBFunctionalExpenseCategory', [CedsOptionSetDescription] = N'Academic support', [CedsOptionSetDefinition] = N'A functional expense category that includes expenses of activities and services that support the institution''s primary missions of instruction, research, and public service. It includes the retention, preservation, and display of educational materials (for example, libraries, museums, and galleries); organized activities that provide support services to the academic functions of the institution (such as a demonstration school associated with a college of education or veterinary and dental clinics if their primary purpose is to support the instructional program); media such as audiovisual services; academic administration (including academic deans but not department chairpersons); and formally organized and separately budgeted academic personnel development and course and curriculum development expenses. Also included are information technology expenses related to academic support activities; if an institution does not separately budget and expense information technology resources, the costs associated with the three primary programs will be applied to this function and the remainder to institutional support. Institutions include actual or allocated costs for operation and maintenance of plant, interest, and depreciation.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001675' AND [CedsOptionSetCode] = N'Academicsupport'
    END

