    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Carpentry', [CedsOptionSetDefinition] = N'Carpentry courses provide information related to the building of wooden structures, enabling students to gain an understanding of wood grades and construction methods and to learn skills such as laying sills and joists; erecting sills and rafters; applying sheathing, siding, and shingles; setting door jambs; and hanging doors. Carpentry courses may teach skills for rough construction, finish work, or both. Students learn to read blueprints, draft, use tools and machines properly and safely, erect buildings from construction lumber, perform finish work inside of buildings, and do limited cabinet work. Carpentry courses may also include career exploration, good work habits, and employability skills.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'17003'
