    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Child Care', [CedsOptionSetDefinition] = N'Child Care courses provide students with knowledge about the physical, mental, emotional, and social growth and development of children from birth through pre-school age. Main topics include the fundamentals of working with infants, toddlers, and older children; providing healthy environments; evaluating child care settings; and examining the practices, regulations, and opportunities in the child care industry. Often Child Care courses provide students with practical experience, including observation time in a child care center. Advanced topics may include various learning theories; development of activities; operation of a child care center; recognition of childhood diseases, abuse, and neglect; and first aid/emergency training.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'19051'
