        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'19255', N'Child Development/Parenting', N'Child Development/Parenting courses provide students with knowledge about family systems and relationships and information about how parents can address the physical, mental, emotional, and social growth and development of children from conception to adolescence. In addition, these courses help students discover how parents should respond to the various stages of childhood. Course content typically includes topics such as prenatal development and birth processes, responsibilities and difficulties of parenthood, family structures, societal and cultural influences, fundamentals of children''s emotional and physical development, and the appropriate care of infants, toddlers, and young and school-aged children. These courses may also cover topics specific to teen parenting.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Child Development/Parenting', [CedsOptionSetDefinition] = N'Child Development/Parenting courses provide students with knowledge about family systems and relationships and information about how parents can address the physical, mental, emotional, and social growth and development of children from conception to adolescence. In addition, these courses help students discover how parents should respond to the various stages of childhood. Course content typically includes topics such as prenatal development and birth processes, responsibilities and difficulties of parenthood, family structures, societal and cultural influences, fundamentals of children''s emotional and physical development, and the appropriate care of infants, toddlers, and young and school-aged children. These courses may also cover topics specific to teen parenting.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'19255'
