        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'24407', N'Chinese Languages for Native Speakers', N'Chinese Languages for Native Speakers courses prepare native and heritage speakers to communicate in Chinese languages in all modes. These courses reinforce and expand students'' skills to interpret (read, listen, view) and present (speak, write) information at the same level as they exchange (speak and listen; read and write) information, concepts, and ideas on a variety of topics. Chinese Languages for Native Speakers courses advance students'' understanding of the relationships among the products, practices, and perspectives of the cultures included in the Chinese language-speaking world. These courses may be used for any Chinese language, including Mandarin and Cantonese.', NULL, N'MISSING')
    END
