        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'05190', N'Fashion Design', N'Fashion Design courses emphasize applying the fundamental processes of artistic expression in creating and merchandising apparel. Drawing the figure is a foundation of these courses. Students identify the relationships between design, clothing and expression of self through fashion statements. Courses may also include a study of historical and contemporary fashion design from a worldwide perspective. Students engage in critique of their designs, the designs of others, and those of professional fashion designers for the purpose of reflecting on and refining work for presentation.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Fashion Design', [CedsOptionSetDefinition] = N'Fashion Design courses emphasize applying the fundamental processes of artistic expression in creating and merchandising apparel. Drawing the figure is a foundation of these courses. Students identify the relationships between design, clothing and expression of self through fashion statements. Courses may also include a study of historical and contemporary fashion design from a worldwide perspective. Students engage in critique of their designs, the designs of others, and those of professional fashion designers for the purpose of reflecting on and refining work for presentation.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'05190'
