        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'05164', N'Fibers and Textile Design', N'Formerly known as Textiles, Fibers and Textile Design courses emphasize applying the fundamental processes of artistic expression in creating textiles and fiber works using fiber and fiber-related media, techniques, and processes. These courses may help students understand the suitability of design to materials and  the artist''s intent in creating textile works of art. Students may create their own work following and breaking from traditional conventions. They may also include the study of the history of fiber and textile art from a worldwide perspective. Students respond to their art and that of others including professional fiber artists through analysis, critique, and interpretation for the purpose of reflecting on and refining work.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Fibers and Textile Design', [CedsOptionSetDefinition] = N'Formerly known as Textiles, Fibers and Textile Design courses emphasize applying the fundamental processes of artistic expression in creating textiles and fiber works using fiber and fiber-related media, techniques, and processes. These courses may help students understand the suitability of design to materials and  the artist''s intent in creating textile works of art. Students may create their own work following and breaking from traditional conventions. They may also include the study of the history of fiber and textile art from a worldwide perspective. Students respond to their art and that of others including professional fiber artists through analysis, critique, and interpretation for the purpose of reflecting on and refining work.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'05164'
