    BEGIN
        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'01153', N'Forensic Speech?Debate', N'Forensic Speech?Debate courses offer students the opportunity to learn how to use oral skills in formal and informal situations. In these courses, students are able to develop such skills as logic and reasoning, research and analysis, organization of thought and supporting materials, argumentative style and skill, and effective presentation of one''s voice and body. Often linked to an extracurricular program, these courses introduce students to the methods, aims, and styles used in various kinds of debates (formal debate or Lincoln-Douglas). Participation in competition is encouraged, but not always required.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
