    END

    IF NOT EXISTS (SELECT 1 FROM [CEDS].[CedsOptionSetMapping] WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'01152')
    BEGIN
        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'01152', N'Forensic Speech?Inclusive', N'Forensic Speech?Inclusive courses offer students the opportunity to learn how to use oral skills effectively in formal and informal situations. Students learn such skills as logic and reasoning, the organization of thought and supporting materials, and effective presentation of one''s voice and body. Often linked to an extracurricular program, these courses introduce students to numerous public speaking situations, and they learn the methods, aims, and styles of a variety of events (e.g., formal debate, Lincoln-Douglas debate, expository speaking, radio broadcast, oral interpretation, and dramatic interpretation). Participation in competition is encouraged, but not always required.', NULL, N'MISSING')
    END
