    BEGIN
        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'18502', N'Forestry Management', N'Formerly known as Forestry, Forestry Management courses provide students with the information and experience necessary for the cultivation, management, and care of forests or timberlands. These courses cover topics such as the processes of regeneration and reforestation, harvesting and conservation of natural resources, erosion and pest control, trail development and maintenance, mapping and surveying, operation of forestry tools, government regulations, environmental stewardship, and urban forestry, including the principles of selecting, planting, and caring for trees in urban settings. Settings may include streets, parks, commercial/industrial landscape settings, and recreational use of forests. These courses also address forestry harvesting and methods to manage, protect, and harvest timber stands and specialty forest crops; equipment maintenance and repair; the selection, planting, transplanting, and harvesting of trees; forest management; and safety procedures.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Forestry Management', [CedsOptionSetDefinition] = N'Formerly known as Forestry, Forestry Management courses provide students with the information and experience necessary for the cultivation, management, and care of forests or timberlands. These courses cover topics such as the processes of regeneration and reforestation, harvesting and conservation of natural resources, erosion and pest control, trail development and maintenance, mapping and surveying, operation of forestry tools, government regulations, environmental stewardship, and urban forestry, including the principles of selecting, planting, and caring for trees in urban settings. Settings may include streets, parks, commercial/industrial landscape settings, and recreational use of forests. These courses also address forestry harvesting and methods to manage, protect, and harvest timber stands and specialty forest crops; equipment maintenance and repair; the selection, planting, transplanting, and harvesting of trees; forest management; and safety procedures.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'18502'
    END

