        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'03157', N'IB Physics', N'IB Physics courses prepare students to take the International Baccalaureate Physics exams. In keeping with the general aim of IB Experimental Sciences courses, IB Physics promotes understanding of the facts, patterns, and principles underlying the field of physics; critical analysis, prediction, and application of scientific information and hypotheses; improved ability to communicate scientific ideas; and an awareness of the impact of scientific advances in physics upon both society and issues of ethical, philosophical, and political importance. Course content varies, but includes the study of physical measurement; mechanics; thermal, atomic, and nuclear physics; oscillations and waves; electric currents; fields and forces; and energy, power, and climate change. Laboratory experimentation is essential; calculus may be used in some courses.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'IB Physics', [CedsOptionSetDefinition] = N'IB Physics courses prepare students to take the International Baccalaureate Physics exams. In keeping with the general aim of IB Experimental Sciences courses, IB Physics promotes understanding of the facts, patterns, and principles underlying the field of physics; critical analysis, prediction, and application of scientific information and hypotheses; improved ability to communicate scientific ideas; and an awareness of the impact of scientific advances in physics upon both society and issues of ethical, philosophical, and political importance. Course content varies, but includes the study of physical measurement; mechanics; thermal, atomic, and nuclear physics; oscillations and waves; electric currents; fields and forces; and energy, power, and climate change. Laboratory experimentation is essential; calculus may be used in some courses.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'03157'
