    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'IB Theory of Knowledge', [CedsOptionSetDefinition] = N'Obligatory for every International Baccalaureate Diploma degree candidate, IB Theory of Knowledge courses aim to stimulate critical self-reflection of students'' knowledge and experiences. Course content generates questions regarding the bases of knowledge and their verification in the disciplines of mathematics, natural sciences, human sciences, the arts, history, ethics, religious knowledge systems, and indigenous knowledge systems, with an awareness of moral, political, and aesthetic judgments and biases. Students learn to appreciate the strengths and limitations of various kinds of knowledge; to relate studied subjects to one another, general knowledge, and living experiences; to formulate rational arguments; and to evaluate the role of language in knowledge and as a way to convey knowledge.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'04304'
