        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'05256', N'Moving Image ? Animation', N'Moving Image?Animation courses explore the creative and conceptual aspects of designing and producing animated images for storytelling and multimedia presentations including dramatic narratives; artistic and experimental presentations and installations; and ambient, interactive, immersive and performance media. Topics may include motion graphics; compositing and visual effects; 2D and 3D animation; timing and spacing; aspect ratio; video editing; animation physics and expressions; pre- and post-production methods, tools and processes; animation presentation, transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Moving Image ? Animation', [CedsOptionSetDefinition] = N'Moving Image?Animation courses explore the creative and conceptual aspects of designing and producing animated images for storytelling and multimedia presentations including dramatic narratives; artistic and experimental presentations and installations; and ambient, interactive, immersive and performance media. Topics may include motion graphics; compositing and visual effects; 2D and 3D animation; timing and spacing; aspect ratio; video editing; animation physics and expressions; pre- and post-production methods, tools and processes; animation presentation, transmission, distribution, and marketing; and contextual, cultural, and historical aspects and considerations.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'05256'
