        INSERT [CEDS].[CedsOptionSetMapping] ([CedsElementName], [CedsElementTechnicalName], [CedsGlobalId], [CedsOptionSetCode], [CedsOptionSetDescription], [CedsOptionSetDefinition], [EdFactsElementName], [EdFactsOptionSetCode]) VALUES (N'School Courses for the Exchange of Data Course Code', N'SCEDCourseCode', N'001517', N'05169', N'Multimedia Art', N'Formerly known as Computer-Assisted Art, Multimedia Art courses emphasize applying the fundamental processes of artistic expression for the purpose of creating multimedia productions that explore contemporary social, cultural, and political issues. These courses include the history and development of multiple forms of media including a combination of text, audio, still images, animation, video, and interactive content. These courses provide students with the opportunity to develop foundational skills and knowledge while they also become more adept in cinema, video, digital live production, and electronic time-based media. Students engage in critique of their multimedia work, that of others, and the multimedia video, digital, and live production work of artists for the purpose of reflecting on and refining work for presentation.', NULL, N'MISSING')
    END
    ELSE IF @updateExisting = 1
    BEGIN
        UPDATE [CEDS].[CedsOptionSetMapping] SET [CedsElementName] = N'School Courses for the Exchange of Data Course Code', [CedsElementTechnicalName] = N'SCEDCourseCode', [CedsOptionSetDescription] = N'Multimedia Art', [CedsOptionSetDefinition] = N'Formerly known as Computer-Assisted Art, Multimedia Art courses emphasize applying the fundamental processes of artistic expression for the purpose of creating multimedia productions that explore contemporary social, cultural, and political issues. These courses include the history and development of multiple forms of media including a combination of text, audio, still images, animation, video, and interactive content. These courses provide students with the opportunity to develop foundational skills and knowledge while they also become more adept in cinema, video, digital live production, and electronic time-based media. Students engage in critique of their multimedia work, that of others, and the multimedia video, digital, and live production work of artists for the purpose of reflecting on and refining work for presentation.', [EdFactsElementName] = NULL, [EdFactsOptionSetCode] = N'MISSING' WHERE [CedsGlobalId] = N'001517' AND [CedsOptionSetCode] = N'05169'
    END

